def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v}
    counts = {c: sum(v == c for row in grid for v in row) for c in colors}
    inner = min(colors, key=counts.get)
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c]]
    r0,r1=min(r for r,c in pts),max(r for r,c in pts)
    c0,c1=min(c for r,c in pts),max(c for r,c in pts)
    ipts=[(r,c) for r,c in pts if grid[r][c]==inner]
    ph=max(r for r,c in ipts)-min(r for r,c in ipts)+1
    pw=max(c for r,c in ipts)-min(c for r,c in ipts)+1
    out=[row[:] for row in grid]
    for r in range(max(0,r0-ph), min(h,r1+ph+1)):
        for c in range(max(0,c0-pw), min(w,c1+pw+1)):
            if out[r][c]==0: out[r][c]=inner
    return out
